void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;
    rephase_limit += 1024;
    for (int i = 1; i <= vars; i++) {
        if (value[i] != 0) {
            saved[i] = value[i];
        } else if (rand() % 100 < 30) {
            saved[i] = local_best[i];
        } else {
            saved[i] = -local_best[i];
        }
    }
}
